import zipfile
import csv

with zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip', 'r') as zf:
    content = zf.read('trips.txt').decode('utf-8')

# Parse trips.txt
trips = {}
for line in content.split(chr(10)):
    if not line.strip():
        continue
    parts = line.split(',')
    if len(parts) >= 4:
        route_id = parts[0]
        service_id = parts[1]
        trip_id = parts[2]
        shape_id = parts[3]
        if route_id not in trips:
            trips[route_id] = []
        trips[route_id].append((service_id, trip_id, shape_id))

# Read stop_times.csv
stop_times = {}
with open('outputs/t05_clean_stop_times.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['stop_id']
        if stop_id not in stop_times:
            stop_times[stop_id] = []
        stop_times[stop_id].append(row)

# Check departure_time type
for stop_id, times in stop_times.items():
    if len(times) > 0:
        for time in times[:5]:
            print(f'{stop_id}: departure_time type: {type(time[\"departure_time\"])} = {repr(time[\"departure_time\"])}')
            break
EOF"}

